OPENQASM 3.0;
include "stdgates.inc";

// data[0] = q1, data[1] = q2, data[2] = q3,
// data[3] = q4, data[4] = q5.
//
// syn  = syndrome ancilla, initialized to |+>
// flag = flag ancilla, initialized to |+>
//
// m = syndrome bit
// f = flag bit
//
// Basis-transformed flag convention:
//   syndrome ancilla: |+>, X-basis measurement
//   flag ancilla:     |0>, Z-basis measurement
//   Z data component: CZ(ancilla, data)
//   X data component: CX(ancilla -> data)
//   Y data component: CY(ancilla -> data)
//   flag-syndrome coupling: CX(syndrome -> flag).
// The syndrome line is Hadamard-transformed, and the flag line is also
// Hadamard-transformed: H_flag CZ(syn,flag) H_flag = CX(syn -> flag).

qubit[5] data;
qubit syn;
qubit flag;

bit m;
bit f;

// Measure a Z component using phase kickback with syn in |+>:
// CZ couples the Z component to the syndrome ancilla.
gate meas_z_component d, a {
    cz d, a;
}

// Measure an X component directly.
// Equivalent to H_d; CZ(d,a); H_d, but written as CX(ancilla -> data).
gate meas_x_component d, a {
    cx a, d;
}

// ------------------------------------------------------------
// Flagged syndrome extraction for G3 = Z X I X Z
// ------------------------------------------------------------

reset syn;
h syn;               // prepare |+> syndrome ancilla
reset flag;

// a: Z on q1
meas_z_component data[0], syn;

// couple syndrome ancilla to flag in the doubly transformed basis
cx syn, flag;

// b: X on q2
meas_x_component data[1], syn;

// c: X on q4
meas_x_component data[3], syn;

// couple syndrome ancilla to flag in the doubly transformed basis
cx syn, flag;

// d: Z on q5
meas_z_component data[4], syn;

// syndrome X-basis measurement
h syn;               // rotate X basis to Z basis for measurement
m = measure syn;

// flag Z-basis measurement
f = measure flag;

files.Bha23_[[7,1,3]]_fig5.fpdl:
protocol Bha23_[[7,1,3]]_fig5:

    code:
        [[7,1,3]]

        [[I,I,I,X,X,X,X],
        [I,X,X,I,I,X,X],
        [X,I,X,I,X,I,X],
        [I,I,I,Z,Z,Z,Z],
        [I,Z,Z,I,I,Z,Z],
        [Z,I,Z,I,Z,I,Z]]

    se:
        IIIXXXX_f {
            file: "./IIIXXXX_f.qasm"
            qd: qd
            qm: qm
            qf: qf
            g: [[I,I,I,X,X,X,X]]
            #-flag: 1
        }

        IXXIIXX_f {
            file: "./IXXIIXX_f.qasm"
            qd: qd
            qm: qm
            qf: qf
            g: [[I,X,X,I,I,X,X]]
            #-flag: 1
        }

        XIXIXIX_f {
            file: "./XIXIXIX_f.qasm"
            qd: qd
            qm: qm
            qf: qf
            g: [[X,I,X,I,X,I,X]]
            #-flag: 1
        }

        IIIZZZZ_f {
            file: "./IIIZZZZ_f.qasm"
            qd: qd
            qm: qm
            qf: qf
            g: [[I,I,I,Z,Z,Z,Z]]
            #-flag: 1
        }

        IZZIIZZ_f {
            file: "./IZZIIZZ_f.qasm"
            qd: qd
            qm: qm
            qf: qf
            g: [[I,Z,Z,I,I,Z,Z]]
            #-flag: 1
        }

        ZIZIZIZ_f {
            file: "./ZIZIZIZ_f.qasm"
            qd: qd
            qm: qm
            qf: qf
            g: [[Z,I,Z,I,Z,I,Z]]
            #-flag: 1
        }

        IIIXXXX_b {
            file: "./IIIXXXX_b.qasm"
            qd: qd
            qm: qm
            g: [[I,I,I,X,X,X,X]]
        }

        IXXIIXX_b {
            file: "./IXXIIXX_b.qasm"
            qd: qd
            qm: qm
            g: [[I,X,X,I,I,X,X]]
        }

        XIXIXIX_b {
            file: "./XIXIXIX_b.qasm"
            qd: qd
            qm: qm
            g: [[X,I,X,I,X,I,X]]
        }

        IIIZZZZ_b {
            file: "./IIIZZZZ_b.qasm"
            qd: qd
            qm: qm
            g: [[I,I,I,Z,Z,Z,Z]]
        }

        IZZIIZZ_b {
            file: "./IZZIIZZ_b.qasm"
            qd: qd
            qm: qm
            g: [[I,Z,Z,I,I,Z,Z]]
        }

        ZIZIZIZ_b {
            file: "./ZIZIZIZ_b.qasm"
            qd: qd
            qm: qm
            g: [[Z,I,Z,I,Z,I,Z]]
        }

        X_SE_b {
            file: "./X_SE_b.qasm"
            qd: qd
            qm: qm
            g: [[I,I,I,X,X,X,X],
                [I,X,X,I,I,X,X],
                [X,I,X,I,X,I,X]]
        }

        Z_SE_b {
            file: "./Z_SE_b.qasm"
            qd: qd
            qm: qm
            g: [[I,I,I,Z,Z,Z,Z],
                [I,Z,Z,I,I,Z,Z],
                [Z,I,Z,I,Z,I,Z]]
        }

    gvar:
        cnt n = 0;
        bit s = 0;
        bit f = 0;
        bit s1 = ⊥;
        bit s2 = ⊥;
        mr  m  = mr[];

    tc:
        1: (s == 1) and (f == 0)
        2: (s1 != ⊥) and (s2 != ⊥)
        3: (n == 6) and (s == 0) and (f == 0)

    af:
        while(!tc) {
            if ((s == 0) and (f == 0)) {
                switch(n) {
                    0: { (s,f) = IIIXXXX_f(); }
                    1: { (s,f) = IXXIIXX_f(); }
                    2: { (s,f) = XIXIXIX_f(); }
                    3: { (s,f) = IIIZZZZ_f(); }
                    4: { (s,f) = IZZIIZZ_f(); }
                    5: { (s,f) = ZIZIZIZ_f(); }
                }
                m.push({s,f});
                n += 1;

            } else { // (s,f) = (0,1) or (1,0)
                switch(n) {
                    1: { (s1,) = IIIXXXX_b(); (s2,) = IIIZZZZ_b(); }
                    2: { (s1,) = IXXIIXX_b(); (s2,) = IZZIIZZ_b(); }
                    3: { (s1,) = XIXIXIX_b(); (s2,) = ZIZIZIZ_b(); }
                    4: { (s1,) = IIIZZZZ_b(); (s2,) = IIIXXXX_b(); }
                    5: { (s1,) = IZZIIZZ_b(); (s2,) = IXXIIXX_b(); }
                    6: { (s1,) = ZIZIZIZ_b(); (s2,) = XIXIXIX_b(); }
                }
                m.push(s1);
                m.push(s2);
            }
        }

    tp:
        1: {
            if (n <= 3) {
                bit[3] sb = ⊥;
                (sb,) = X_SE_b();
                m.push(sb);
                switch(n) {
                    1: { (s,) = IIIZZZZ_b(); }
                    2: { (s,) = IZZIIZZ_b(); }
                    3: { (s,) = ZIZIZIZ_b(); }
                }
                m.push(s);
                decode(m);
            } else {
                bit[3] sb = ⊥;
                (sb,) = Z_SE_b();
                m.push(sb);
                switch(n) {
                    1: { (s,) = IIIXXXX_b(); }
                    2: { (s,) = IXXIIXX_b(); }
                    3: { (s,) = XIXIXIX_b(); }
                }
                m.push(s);
                decode(m);
            }
        }

        2: {
            switch(n) {
                1: { 
                    bit s_next = ⊥;
                    if (s1 == 0) { (s_next,) = ZIZIZIZ_b(); }
                    else { (s_next,) = XIXIXIX_b(); }
                    m.push(s_next);
                }
                2: { 
                    bit s_next = ⊥;
                    if (s1 == 0) { (s_next,) = ZIZIZIZ_b(); }
                    else { (s_next,) = XIXIXIX_b(); }
                    m.push(s_next);
                }
                3: { 
                    bit s_next = ⊥;
                    if (s1 == 0) { (s_next,) = IZZIIZZ_b(); }
                    else { (s_next,) = IXXIIXX_b(); }
                    m.push(s_next);
                }
                4: { 
                    bit s_next = ⊥;
                    if (s1 == 0) { (s_next,) = XIXIXIX_b(); }
                    else { (s_next,) = ZIZIZIZ_b(); }
                    m.push(s_next);
                }
                5: { 
                    bit s_next = ⊥;
                    if (s1 == 0) { (s_next,) = XIXIXIX_b(); }
                    else { (s_next,) = ZIZIZIZ_b(); }
                    m.push(s_next);
                }
                6: { 
                    bit s_next = ⊥;
                    if (s1 == 0) { (s_next,) = IXXIIXX_b(); }
                    else { (s_next,) = IZZIIZZ_b(); }
                    m.push(s_next);
                }
            }
            decode(m);
        }

        3: {
            end();
        }

files.IIIXXXX_b.qasm:
OPENQASM 3.0;
include "stdgates.inc";

// Syndrome extraction for Steane [[7,1,3]] stabilizer IIIXXXX.
// Controlled-P normal form: qm[0] is the syndrome ancilla, prepared in |+>
// and read in the X basis (final H shown).
qubit[7] qd;
qubit[1] qm;
bit[1] cm;

h qm[0];

// X on qd[3]
cx qm[0], qd[3];

// X on qd[4]
cx qm[0], qd[4];

// X on qd[5]
cx qm[0], qd[5];

// X on qd[6]
cx qm[0], qd[6];

h qm[0];

// Syndrome readout: the final H above rotated the X-basis value into
// the Z basis, so these are plain measurements.
cm[0] = measure qm[0];

