        [I,X,X,I,I,X,X],
        [X,I,X,I,X,I,X],
        [I,I,I,Z,Z,Z,Z],
        [I,Z,Z,I,I,Z,Z],
        [Z,I,Z,I,Z,I,Z]]

    se:
