cx syn[2], data[14];  // Fig.22 gate 50: q15 - m3
cx syn[3], data[7];  // Fig.22 gate 51: q8 - m4
cx syn[5], flag[6];  // Fig.22 gate 52: m6 - f7
cx syn[6], data[10];  // Fig.22 gate 53: q11 - m7
cx syn[7], data[15];  // Fig.22 gate 54: q16 - m8
