files.FSE_b.qasm:
OPENQASM 3.0;
include "stdgates.inc";

// [[5,1,3]] complete RAW (unflagged) syndrome extraction for the same
// independent generator set used by Liou & Lai's fully-parallel [1,1,1,1]^T
// flagged scheme in Fig. 8 of arXiv:2407.00607.
//
//   g1 = X Z Z X I
//   g2 = I X Z Z X
//   g3 = X I X Z Z
//   g4 = Z X I X Z
//
// This file keeps the same cyclic/interleaved data-gate ordering as Fig. 8,
// but removes the two flag-coupling layers. Hence the two-qubit data-SE part
// has depth 4 and uses 16 two-qubit gates.
//
// data[0..4] = physical data qubits 1..5.
// syn[0..3]  = measurement qubits m1..m4, prepared in |+> and measured in X.

qubit[5] data;
qubit[4] syn;
bit[4] m;

// Prepare measurement ancillas in |+>.
reset syn[0];
h syn[0];
reset syn[1];
h syn[1];
reset syn[2];
h syn[2];
reset syn[3];
h syn[3];

// ------------------------------------------------------------
// Two-qubit depth 1: X layer.
// g1:X1, g2:X2, g3:X3, g4:X4
// ------------------------------------------------------------
cx syn[0], data[0];
cx syn[1], data[1];
cx syn[2], data[2];
cx syn[3], data[3];

// ------------------------------------------------------------
// Two-qubit depth 2: Z layer.
// g1:Z2, g2:Z3, g3:Z4, g4:Z5
// ------------------------------------------------------------
cz syn[0], data[1];
cz syn[1], data[2];
cz syn[2], data[3];
cz syn[3], data[4];

// ------------------------------------------------------------
// Two-qubit depth 3: Z layer.
// g1:Z3, g2:Z4, g3:Z5, g4:Z1
// ------------------------------------------------------------
cz syn[0], data[2];
cz syn[1], data[3];
cz syn[2], data[4];
cz syn[3], data[0];

// ------------------------------------------------------------
// Two-qubit depth 4: X layer.
// g1:X4, g2:X5, g3:X1, g4:X2
// ------------------------------------------------------------
cx syn[0], data[3];
cx syn[1], data[4];
cx syn[2], data[0];
cx syn[3], data[1];

// Measure complete syndrome in the X basis.
h syn[0];
m[0] = measure syn[0];
h syn[1];
m[1] = measure syn[1];
h syn[2];
m[2] = measure syn[2];
h syn[3];
m[3] = measure syn[3];

files.FSE_f.qasm:
OPENQASM 3.0;
include "stdgates.inc";

// Liou & Lai, arXiv:2407.00607, Fig. 8.
// [[5,1,3]] fully-parallel [1,1,1,1]^T flagged full syndrome extraction.
//
// Independent generators measured in this circuit:
//   g1 = X Z Z X I
//   g2 = I X Z Z X
//   g3 = X I X Z Z
//   g4 = Z X I X Z
//
// data[0..4] = physical data qubits 1..5.
// syn[0..3]  = measurement qubits m1..m4, prepared in |+> and measured in X.
// flag[0..3] = flag qubits f1..f4, prepared in |0> and measured in Z.
//
// The two-qubit part has depth 6 and 24 two-qubit gates, matching Fig. 8.

qubit[5] data;
qubit[4] syn;
qubit[4] flag;
bit[4] m;
bit[4] f;

// Prepare measurement ancillas in |+>.
reset syn[0];
h syn[0];
reset syn[1];
h syn[1];
reset syn[2];
h syn[2];
reset syn[3];
h syn[3];

// Prepare flag ancillas in |0>.
reset flag[0];
reset flag[1];
reset flag[2];
reset flag[3];

// ------------------------------------------------------------
// Two-qubit depth 1: first X component of each generator.
// g1:X1, g2:X2, g3:X3, g4:X4
// ------------------------------------------------------------
cx syn[0], data[0];
cx syn[1], data[1];
cx syn[2], data[2];
cx syn[3], data[3];

// ------------------------------------------------------------
// Two-qubit depth 2: first flag coupling.
// ------------------------------------------------------------
cx syn[0], flag[0];
cx syn[1], flag[1];
cx syn[2], flag[2];
cx syn[3], flag[3];

// ------------------------------------------------------------
// Two-qubit depth 3: first Z component of each generator.
// g1:Z2, g2:Z3, g3:Z4, g4:Z5
// ------------------------------------------------------------
cz syn[0], data[1];
cz syn[1], data[2];
cz syn[2], data[3];
cz syn[3], data[4];

// ------------------------------------------------------------
// Two-qubit depth 4: second Z component of each generator.
// g1:Z3, g2:Z4, g3:Z5, g4:Z1
// ------------------------------------------------------------
cz syn[0], data[2];
cz syn[1], data[3];
cz syn[2], data[4];
cz syn[3], data[0];

// ------------------------------------------------------------
// Two-qubit depth 5: second flag coupling.
// ------------------------------------------------------------
cx syn[0], flag[0];
cx syn[1], flag[1];
cx syn[2], flag[2];
cx syn[3], flag[3];

// ------------------------------------------------------------
// Two-qubit depth 6: second X component of each generator.
// g1:X4, g2:X5, g3:X1, g4:X2
// ------------------------------------------------------------
cx syn[0], data[3];
cx syn[1], data[4];
cx syn[2], data[0];
cx syn[3], data[1];

// Measure syndrome ancillas in the X basis.
h syn[0];
m[0] = measure syn[0];
h syn[1];
m[1] = measure syn[1];
h syn[2];
m[2] = measure syn[2];
h syn[3];
m[3] = measure syn[3];

// Measure flags in the Z basis.
f[0] = measure flag[0];
f[1] = measure flag[1];
f[2] = measure flag[2];
f[3] = measure flag[3];

files.LL25_[[5,1,3]]_[1,1,1,1]^T.fpdl:
protocol LL25_[[5,1,3]]_[1,1,1,1]^T:

    code:
        [[5,1,3]]

        [[X,Z,Z,X,I],
         [I,X,Z,Z,X],
         [X,I,X,Z,Z],
         [Z,X,I,X,Z]]

    se:
        FSE_b {
            file: "./FSE_b.qasm"
            qd: data
            qm: syn
            g: [[X,Z,Z,X,I],
                [I,X,Z,Z,X],
                [X,I,X,Z,Z],
                [Z,X,I,X,Z]]
        }

        FSE_f {
            file: "./FSE_f.qasm"
            qd: data
            qm: syn
            qf: flag
            g: [[X,Z,Z,X,I],
                [I,X,Z,Z,X],
                [X,I,X,Z,Z],
                [Z,X,I,X,Z]]
            #-flag: 1
        }

    gvar:
        bit[4] m = ⊥;
        bit[]  f = ⊥;

    tc:
        1: (m == 0) and (f == 0)
        2: ((m != 0) or (f != 0)) and (m != ⊥)

    af:
        while(!tc) {
            (m,f) = FSE_f();
        }

    tp:
        1: { 
            end();
        }

        2: {
            bit[4] mp = ⊥;
            (mp,) = FSE_b();
            decode(mr[m, f, mp]);
        }

files.FSE_b.qasm:
OPENQASM 3.0;
include "stdgates.inc";

// [[5,1,3]] complete RAW / unflagged SE for g1,g5,g3,g4.
// Serial version, matching the generator-by-generator raw-SE style used
// by Liou & Lai's flag-sharing serial simulation code.
//
//   g1 = X Z Z X I
//   g5 = Z Z X I X
//   g3 = X I X Z Z
//   g4 = Z X I X Z
//
// One measurement ancilla is reset and reused four times.
// m[0..3] = (m1,m5,m3,m4).

qubit[5] data;
qubit[2] syn;
bit[4] m;

reset syn[0];
reset syn[1];
h syn[0];
h syn[1];
cz syn[0], data[1];
cx syn[1], data[2];
cz syn[0], data[2];
cx syn[0], data[3];
cz syn[1], data[4];
cx syn[1], data[0];
cx syn[0], data[0];
cz syn[1], data[3];
h syn[0];
h syn[1];
m[0] = measure syn[0];
m[1] = measure syn[1];

reset syn[0];
reset syn[1];
h syn[0];
h syn[1];
cz syn[0], data[0];
cx syn[1], data[3];
cz syn[0], data[1];
cz syn[1], data[0];
cx syn[0], data[2];
cx syn[1], data[1];
cx syn[0], data[4];
cz syn[1], data[4];
h syn[0];
h syn[1];
m[2] = measure syn[0];
m[3] = measure syn[1];

files.FSE_f.qasm:
OPENQASM 3.0;
include "stdgates.inc";

// Liou & Lai, arXiv:2407.00607, Fig. 9.
// [[5,1,3]] sequential [2,2] flag-sharing full syndrome extraction.
//
// Measured stabilizers, in generalized-syndrome order m1534:
//   g1 = X Z Z X I
//   g5 = Z Z X I X
//   g3 = X I X Z Z
//   g4 = Z X I X Z
//
// Part (a): g1 and g3 share one flag qubit.
// Part (b): g5 and g4 share one flag qubit.
// The same two measurement qubits and one flag qubit are reset/reused.
// Each part has two-qubit depth 7; total flagged depth = 14.
// Total two-qubit gates = 24.
//
// data[0..4] = physical data qubits 1..5.
// syn[0],syn[1] = the two measurement ancillas used in each part.
// flag[0] = the shared flag ancilla, reused between parts.
// m[0..3] = (m1,m5,m3,m4).
// f[0..1] = (f1,f2).

qubit[5] data;
qubit[2] syn;
qubit[1] flag;
bit[4] m;
bit[2] f;

// ============================================================
// Fig. 9(a): g1 (syn[0] -> m1) and g3 (syn[1] -> m3), shared f1.
// ============================================================
reset syn[0];
h syn[0];
reset syn[1];
h syn[1];
reset flag[0];

// depth 1: g1:Z2, g3:X3
cz syn[0], data[1];
cx syn[1], data[2];

// depth 2: a = first g1--f1 coupling
cx syn[0], flag[0];

// depth 3: g1:Z3, b = first g3--f1 coupling
cz syn[0], data[2];
cx syn[1], flag[0];

// depth 4: g1:X4, g3:Z5
cx syn[0], data[3];
cz syn[1], data[4];

// depth 5: c = second g1--f1 coupling, g3:X1
cx syn[0], flag[0];
cx syn[1], data[0];

// depth 6: g1:X1, d = second g3--f1 coupling
cx syn[0], data[0];
cx syn[1], flag[0];

// depth 7: g3:Z4
cz syn[1], data[3];

// Measure m1,m3 in X basis and f1 in Z basis.
h syn[0];
m[0] = measure syn[0];
h syn[1];
m[2] = measure syn[1];
f[0] = measure flag[0];

// ============================================================
// Fig. 9(b): g5 (syn[0] -> m5) and g4 (syn[1] -> m4), shared f2.
// ============================================================
reset syn[0];
h syn[0];
reset syn[1];
h syn[1];
reset flag[0];

// depth 1: g5:Z1, g4:X4
cz syn[0], data[0];
cx syn[1], data[3];

// depth 2: e = first g5--f2 coupling
cx syn[0], flag[0];

// depth 3: g5:Z2, f = first g4--f2 coupling
cz syn[0], data[1];
cx syn[1], flag[0];

// depth 4: g5:X3, g4:Z1
cx syn[0], data[2];
cz syn[1], data[0];

// depth 5: g = second g5--f2 coupling, g4:X2
cx syn[0], flag[0];
cx syn[1], data[1];

// depth 6: g5:X5, h = second g4--f2 coupling
cx syn[0], data[4];
cx syn[1], flag[0];

// depth 7: g4:Z5
cz syn[1], data[4];

// Measure m5,m4 in X basis and f2 in Z basis.
h syn[0];
m[1] = measure syn[0];
h syn[1];
m[3] = measure syn[1];
f[1] = measure flag[0];

